(function () { if (window.MIGLANG !== "en" || !window.I18N_EN) return; var N = /[0-9٠-٩][0-9٠-٩,.:%\/\-]*/g, K = function (s) { return String(s).replace(/\s+/g, " ").trim().replace(N, "{n}"); }, P = window.MIGOLDFACD_PFX, D = window.MIGOLDFACD; for (var i in P) { var k = K(D[i]); if (I18N_EN[k] == null) { var v = I18N_EN[K(P[i] + " | " + D[i])]; if (v != null) I18N_EN[k] = v; } } })();

